import{_ as a}from"./chunks/0.1.60-rules-test-193.BIxiAEmj.js";import{_ as t,o as n,c as r,a3 as s}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse('{"title":"Rules","description":"","frontmatter":{},"headers":[],"relativePath":"fr/projects/logic-studio/user-guide/rules.md","filePath":"fr/projects/logic-studio/user-guide/rules.md","lastUpdated":1794769275000}'),i={name:"fr/projects/logic-studio/user-guide/rules.md"};function o(l,e,u,c,d,h){return n(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h1><h2 id="premier-exemple" tabindex="-1">Premier exemple <a class="header-anchor" href="#premier-exemple" aria-label="Permalink to &quot;Premier exemple&quot;">​</a></h2><p>Dans l’assistant, choisis un déclencheur d’état, ton entrée de test et <code>on</code>. Ajoute une action ALORS pour activer une seconde entrée. Exporte le YAML et vérifie-le dans HA.</p><p>L’éditeur Rules affiche la palette à gauche et les sections SI, ALORS et SINON dans la zone de travail.</p><p><img src="'+a+'" alt="Éditeur Rules avec palette et branches"></p><h2 id="fonctions" tabindex="-1">Fonctions <a class="header-anchor" href="#fonctions" aria-label="Permalink to &quot;Fonctions&quot;">​</a></h2><h3 id="assistant-et-palette" tabindex="-1">Assistant et palette <a class="header-anchor" href="#assistant-et-palette" aria-label="Permalink to &quot;Assistant et palette&quot;">​</a></h3><p>L’assistant guide la création. Tu peux aussi chercher et glisser un élément de la palette vers la section voulue.</p><h3 id="declencheurs" tabindex="-1">Déclencheurs <a class="header-anchor" href="#declencheurs" aria-label="Permalink to &quot;Déclencheurs&quot;">​</a></h3><p>Choisis un état avec valeurs avant/après, attribut et durée, un seuil, une heure fixe ou issue d’une entrée, le soleil avec décalage, MQTT, un événement HA, le démarrage de HA, une zone ou une étiquette.</p><h3 id="conditions" tabindex="-1">Conditions <a class="header-anchor" href="#conditions" aria-label="Permalink to &quot;Conditions&quot;">​</a></h3><p>Vérifie un état, un nombre, un attribut, une heure ou un jour. ET exige toutes les conditions, OU au moins une et NON inverse le résultat.</p><h3 id="declenche-par" tabindex="-1">Déclenché par <a class="header-anchor" href="#declenche-par" aria-label="Permalink to &quot;Déclenché par&quot;">​</a></h3><p>Donne aux déclencheurs des identifiants comme <code>first</code> et <code>second</code>. Vérifie l’identifiant pour choisir entre ALORS et SINON.</p><h3 id="modele" tabindex="-1">Modèle <a class="header-anchor" href="#modele" aria-label="Permalink to &quot;Modèle&quot;">​</a></h3><p>En mode expert, ajoute une condition de modèle native HA. Son résultat indique si la condition est remplie.</p><h3 id="actions-et-branches" tabindex="-1">Actions et branches <a class="header-anchor" href="#actions-et-branches" aria-label="Permalink to &quot;Actions et branches&quot;">​</a></h3><p>Ajoute les actions dans l’ordre souhaité. Choisis une cible et des paramètres, ajoute un délai, attends un état, appelle un script ou envoie une notification.</p><h3 id="yaml-et-json-rules" tabindex="-1">YAML et JSON Rules <a class="header-anchor" href="#yaml-et-json-rules" aria-label="Permalink to &quot;YAML et JSON Rules&quot;">​</a></h3><p>Utilise le YAML dans HA et le JSON Rules pour rouvrir la règle dans l’éditeur.</p><h2 id="en-cas-de-probleme" tabindex="-1">En cas de problème <a class="header-anchor" href="#en-cas-de-probleme" aria-label="Permalink to &quot;En cas de problème&quot;">​</a></h2><p>Un seuil se déclenche à nouveau après une sortie puis une nouvelle entrée dans la plage.</p>',22)])])}const f=t(i,[["render",o]]);export{b as __pageData,f as default};
